package br.com.seucusto.app.data
import androidx.room.*
import kotlinx.coroutines.flow.Flow
@Dao interface ProductDao{ @Query("SELECT * FROM products ORDER BY name") fun observeAll():Flow<List<ProductEntity>>; @Query("SELECT * FROM products WHERE id=:id LIMIT 1") suspend fun find(id:String):ProductEntity?; @Insert(onConflict=OnConflictStrategy.ABORT) suspend fun insert(item:ProductEntity); @Update suspend fun update(item:ProductEntity)}
@Dao interface RawMaterialDao{ @Query("SELECT * FROM raw_materials ORDER BY name") fun observeAll():Flow<List<RawMaterialEntity>>; @Query("SELECT * FROM raw_materials WHERE id=:id LIMIT 1") suspend fun find(id:String):RawMaterialEntity?; @Insert(onConflict=OnConflictStrategy.ABORT) suspend fun insert(item:RawMaterialEntity); @Update suspend fun update(item:RawMaterialEntity)}
@Dao interface ProductComponentDao{ @Query("SELECT COUNT(*) FROM product_components WHERE rawMaterialId=:rawMaterialId") suspend fun countByRawMaterial(rawMaterialId:String):Int; @Query("SELECT * FROM product_components WHERE productId=:productId") fun observeForProduct(productId:String):Flow<List<ProductComponentEntity>>; @Insert(onConflict=OnConflictStrategy.REPLACE) suspend fun upsert(item:ProductComponentEntity); @Query("DELETE FROM product_components WHERE productId=:productId AND rawMaterialId=:rawMaterialId") suspend fun delete(productId:String,rawMaterialId:String)}
@Dao interface StockDao{ @Query("SELECT * FROM stock ORDER BY rawMaterialId") fun observeAll():Flow<List<StockEntity>>; @Query("SELECT * FROM stock WHERE rawMaterialId=:id LIMIT 1") suspend fun find(id:String):StockEntity?; @Insert(onConflict=OnConflictStrategy.REPLACE) suspend fun upsert(item:StockEntity); @Insert suspend fun addMovement(item:StockMovementEntity)}
